use super::*;
fn bank()->V{json!({"schemaVersion":2,"mode":"source_probability_actual_receipt_paper","name":"fixture-only","cutoff":"2026-10-01T00:00:00.000Z","universe":{"tournamentId":"bda92870-621e-47b0-bc3c-3602c5c26f55","exchanges":[{"marketId":"305","exchangeId":"994","option":"YES"}]},"identities":{"305":{"exchangeId":"994","predicateHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}},"research":[{"schemaVersion":1,"id":"fixture","marketId":"305","exchangeId":"994","side":"YES","predicateHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","recordedAt":"2026-10-01T00:00:00.000Z","sourceAt":"2026-10-01T00:00:00.000Z","expiresAt":"2026-10-01T06:00:00.000Z","lower":"0.950000","upper":"0.990000","method":"subjective_range","settlementReviewed":true,"flags":[],"sources":[{"url":"https://example.org/fixture","contentHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]}],"policy":{"minimumLowerEdge":"0.020000","maximumSpread":"0.020000","maximumResearchAgeMs":21600000,"maximumAccountAgeMs":20000,"maxHoldMs":172800000,"takeProfit":"0.020000","maxMarketCost":"1.000000","maxOpenMarkets":3,"cumulativeBuyBudget":"100.000000","latenciesMs":[1000,3000]},"config":{"schemaVersion":1,"initialCash":"100.000000","tournamentSlug":"midterm-elections","tournamentId":"bda92870-621e-47b0-bc3c-3602c5c26f55","marketIds":["305"],"readIntervalMs":6000,"cycleIntervalMs":30000,"maxDataAgeMs":20000,"latencyMs":1000,"feeBps":0,"slippageTicks":1,"depthFractionBps":100,"orderShares":1,"maxPositionShares":1,"maxExposure":"10.000000","cashReserve":"90.000000","warmupObservations":5,"lookback":30,"entryZ":1.5,"minEdge":"0.015000","exitAfterMs":172800000,"stopLoss":"0.050000","port":8787,"strategyUniverse":"diversified-dip-v1"}})}
fn stamp(second:u32)->String{format!("2026-10-01T00:00:{second:02}.000Z")}
fn event(second:u32,seq:u32,bid:&str,ask:&str,depth:i64)->V{let received=stamp(second);let request=stamp(second-1);let source=format!("2026-10-01T00:00:{:02}.000000000Z",second-1);json!({"row":{"kind":"book","at":received,"sequence":seq,"hash":format!("{:064x}",seq),"payload":{"book":{"tournamentId":"bda92870-621e-47b0-bc3c-3602c5c26f55","marketId":"305","exchangeId":"994","instrument":"994:YES","receivedAt":received,"requestStartedAt":request,"sourceAt":source,"sequence":seq.to_string(),"versionKey":format!("{seq}:{source}"),"bids":[{"price":bid,"quantity":depth}],"asks":[{"price":ask,"quantity":depth}],"freshnessPolicy":"authoritative_receipt_v1","sourceEventAgeMs":1000}}},"availableAt":received,"accountEligibility":{"schemaVersion":1,"positionsAt":request,"ordersAt":request,"excludedExchangeIds":[]}})}
#[test]fn canonical_keys_floats_and_money_match_js_rules(){let v:V=serde_json::from_str(r#"{"a":1,"10":10,"2":2,"x":1e-7,"z":-0.0}"#).unwrap();assert_eq!(canonical(&v),r#"{"2":2,"10":10,"a":1,"x":1e-7,"z":0}"#);assert_eq!(money(amount(&json!("0.125000")).unwrap()),json!("0.125000"));assert!(amount(&json!("0.0000001")).is_err());}
#[test]fn later_request_latency_depth_and_exact_basis_are_enforced(){let mut e=Engine::new(bank()).unwrap();e.apply(&event(3,1,"0.115000","0.120000",100)).unwrap();let report=e.report(&stamp(3)).unwrap();assert_eq!(report["wallets"]["1000"]["fills"],0);e.apply(&event(8,2,"0.115000","0.120000",99)).unwrap();assert_eq!(e.report(&stamp(8)).unwrap()["wallets"]["1000"]["fills"],0);e.apply(&event(13,3,"0.115000","0.120000",100)).unwrap();for latency in ["1000","3000"]{let st=&e.state()["wallets"][latency]["state"]["strategies"]["mean_reversion"];assert_eq!(st["cash"],"99.875000");assert_eq!(st["positions"]["994:YES"]["cost"],"0.125000");assert_eq!(st["fees"],"0.000000");}}
#[test]fn entry_drain_blocks_only_new_intents_preserving_attributed_pending_buy(){let mut e=Engine::new(bank()).unwrap();e.apply_with_entry_permission(&event(3,1,"0.115000","0.120000",100),false).unwrap();assert_eq!(e.state()["wallets"]["1000"]["state"]["strategies"]["mean_reversion"]["intents"],0);e.apply(&event(8,2,"0.115000","0.120000",100)).unwrap();e.apply_with_entry_permission(&event(13,3,"0.115000","0.120000",100),false).unwrap();assert_eq!(e.report(&stamp(13)).unwrap()["wallets"]["1000"]["fills"],1);}
#[test]fn held_take_profit_closes_later_and_preserves_realized_fifo(){let mut e=Engine::new(bank()).unwrap();e.apply(&event(3,1,"0.115000","0.120000",100)).unwrap();e.apply(&event(8,2,"0.115000","0.120000",100)).unwrap();e.apply_with_entry_permission(&event(13,3,"0.150000","0.155000",100),false).unwrap();assert_eq!(e.report(&stamp(13)).unwrap()["wallets"]["1000"]["fills"],1);e.apply_with_entry_permission(&event(18,4,"0.150000","0.155000",100),false).unwrap();let r=e.report(&stamp(18)).unwrap();assert_eq!(r["wallets"]["1000"]["cash"],"100.020000");assert_eq!(r["wallets"]["1000"]["realizedPnl"],"0.020000");assert_eq!(r["wallets"]["1000"]["closedTrades"],1);assert_eq!(r["wallets"]["1000"]["pending"].as_array().unwrap().len(),0);}
#[test]fn missing_or_future_account_blocks_fills_and_keeps_held_inventory(){let mut e=Engine::new(bank()).unwrap();e.apply(&event(3,1,"0.115000","0.120000",100)).unwrap();e.apply(&event(8,2,"0.115000","0.120000",100)).unwrap();let mut bad=event(13,3,"0.150000","0.155000",100);bad["accountEligibility"]=V::Null;e.apply(&bad).unwrap();assert_eq!(e.report(&stamp(13)).unwrap()["wallets"]["1000"]["fills"],1);assert_eq!(e.state()["counts"]["account_unavailable"],1);assert_eq!(e.report(&stamp(13)).unwrap()["wallets"]["1000"]["positions"].as_array().unwrap().len(),1);}
#[test]fn bad_funded_import_cannot_reset_or_fabricate_cash(){let e=Engine::new(bank()).unwrap();let mut s=e.state().clone();s["wallets"]["1000"]["state"]["strategies"]["mean_reversion"]["cash"]=json!("101.000000");assert!(Engine::restore(bank(),s).is_err());}
#[test]fn conflicting_version_and_clock_rollback_preserve_prior_state(){let mut e=Engine::new(bank()).unwrap();e.apply(&event(3,1,"0.115000","0.120000",100)).unwrap();let before=digest(e.state());let mut bad=event(8,1,"0.110000","0.115000",100);bad["row"]["payload"]["book"]["sourceAt"]=json!("2026-10-01T00:00:02.000000000Z");bad["row"]["payload"]["book"]["versionKey"]=json!("1:2026-10-01T00:00:02.000000000Z");assert!(e.apply(&bad).is_err());assert_eq!(digest(e.state()),before);let mut bad=event(2,2,"0.115000","0.120000",100);bad["availableAt"]=json!(stamp(2));assert!(e.apply(&bad).is_err());assert_eq!(digest(e.state()),before);}
#[test]fn fee_rounding_is_integer_ceiling_without_rebates(){let mut c=bank()["config"].clone();c["feeBps"]=json!(1);assert_eq!(fee(1,&c).unwrap(),1);assert_eq!(fee(10001,&c).unwrap(),2);}
